// Единый дедуп: внутри пачки (по ссылке) + по истории публикаций (ссылка/заголовок).
// Сам пополняет историю — ловит повторы и между разными RSS-лентами.
const sd = $getWorkflowStaticData('global');
const history = Array.isArray(sd.published) ? sd.published : [];

const STOP = new Set(['the', 'a', 'an', 'of', 'in', 'on', 'to', 'for', 'and', 'or', 'at', 'by', 'with', 'from',
  'is', 'are', 'was', 'were', 'be', 'been', 'it', 'its', 'this', 'that', 'these', 'those', 'as', 'after',
  'before', 'over', 'under', 'new', 'says', 'said', 'will', 'has', 'have', 'had', 'not', 'but', 'you', 'your',
  'how', 'why', 'what', 'when', 'where', 'who', 'vs', 'via', 'into', 'out', 'up', 'down', 'more', 'most']);

function norm(s) {
  return String(s || '').toLowerCase()
    .replace(/https?:\/\/\S+/g, ' ')
    .replace(/[^0-9a-zа-яіїєґ\s]/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}
function normLink(u) {
  return String(u || '').toLowerCase().replace(/\/+$/, '').split('?')[0];
}
function tokens(s) {
  const out = new Set();
  for (const w of norm(s).split(' ')) {
    if (w.length > 2 && !STOP.has(w)) out.add(w);
  }
  return out;
}
function jaccard(a, b) {
  if (!a.size || !b.size) return 0;
  let inter = 0;
  for (const w of a) if (b.has(w)) inter++;
  return inter / (a.size + b.size - inter);
}

const out = [];
const passed = [];
for (const item of $input.all()) {
  const link = normLink(item.json?.link || item.json?.guid || '');
  const t = tokens(item.json?.title || '');
  let dup = false;
  for (const h of history.concat(passed)) {
    if (!h) continue;
    const hl = typeof h === 'string' ? h : h.l;
    if (link && hl && normLink(hl) === link) { dup = true; break; }
    if (t.size && h.t && jaccard(t, tokens(h.t)) >= 0.6) { dup = true; break; }
  }
  if (!dup) {
    out.push(item);
    passed.push({ l: link, t: String(item.json?.title || '').slice(0, 160) });
  }
}
sd.published = history.concat(passed).slice(-300);
return out;

const item = $input.item.json;
const cleanText = (item.contentSnippet || item.title || '').replace(/<[^>]*>/g, '').replace(/\s+/g, ' ').trim().substring(0, 4000);

let imageUrl = '';

// 1. RSS enclosure / media:content
try {
  if (item.enclosure && item.enclosure.url) imageUrl = item.enclosure.url;
  else if (item['media:content'] && item['media:content'].url) imageUrl = item['media:content'].url;
} catch (e) {}

// 2. <img> from content HTML
if (!imageUrl && item.content) {
  try {
    const m = item.content.match(/<img[^>]+src=["']([^"']+)["']/i);
    if (m && m[1]) imageUrl = m[1];
  } catch (e) {}
}

// 3. og:image via fetch with timeout
if (!imageUrl && item.link) {
  try {
    const ctrl = new AbortController();
    setTimeout(() => ctrl.abort(), 3000);
    const res = await fetch(item.link, { signal: ctrl.signal });
    const html = await res.text();
    const m = html.match(/<meta[^>]+property=["']og:image["'][^>]+content=["']([^"']+)["']/i)
           || html.match(/<meta[^>]+content=["']([^"']+)["'][^>]+property=["']og:image["']/i);
    if (m && m[1]) imageUrl = m[1];
  } catch (e) {}
}

// 4. Normalize relative URLs
if (imageUrl && imageUrl.startsWith('/') && item.link) {
  try {
    const u = new URL(item.link);
    imageUrl = u.origin + imageUrl;
  } catch (e) {}
}

// URL Normalization: strip tracking params
let cleanLink = item.link || '';
try {
  const parsed = new URL(cleanLink);
  const paramsToKeep = new URLSearchParams();
  for (const [key, val] of parsed.searchParams.entries()) {
    if (!key.startsWith('utm_') && !['ref', 'fbclid', 'gclid', 'mc_cid', 'mc_eid'].includes(key.toLowerCase())) {
      paramsToKeep.append(key, val);
    }
  }
  const searchStr = paramsToKeep.toString();
  cleanLink = parsed.origin + parsed.pathname + (searchStr ? '?' + searchStr : '');
} catch (e) {
  cleanLink = (item.link || '').split('?')[0];
}
cleanLink = cleanLink.toLowerCase().replace(/\/+$/, '');

return {
  title: item.title,
  link: cleanLink,
  sourceText: cleanText,
  imageUrl: imageUrl
};

const aiContent = $json.output || $json.text || ($json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content);
let aiResponse = {};

try {
    if (typeof aiContent === 'string') {
        const cleanJson = aiContent.replace(/```json/gi, '').replace(/```/gi, '').trim();
        aiResponse = JSON.parse(cleanJson);
    } else {
        aiResponse = aiContent || {};
    }
} catch (e) {
    const jsonMatch = String(aiContent).match(/\{[\s\S]*\}/);
    aiResponse = jsonMatch ? JSON.parse(jsonMatch[0]) : {};
}

let link = $json.link || $('Preprocessing').item.json.link || '#';
const imageUrl = $json.imageUrl || $('Preprocessing').item.json.imageUrl || '';

// --- shortener: cut text but keep a "...…" ellipse so it is not abrupt ---
function clip(s, max) {
    s = String(s || '');
    if (s.length <= max) return s;
    return s.substring(0, max - 1) + '…';
}

if (!aiResponse.title_uk && !aiResponse.content_uk) {
    return {
        fullText: '🔴 <b>ПОМИЛКА</b>\n\n' + clip(aiContent, 400) + '\n\nДжерело:\n🔗 <b><a href="' + link + '">Читати</a></b>',
        imageUrl: imageUrl,
        importance: 'Низька',
        reaction: '',
        link: link,
        relevance_score: aiResponse.relevance_score || 50
    };
}

const title = clip(aiResponse.title_uk || 'Новина', 120);
const content = clip(aiResponse.content_uk || '', 420);
const analysis = clip(aiResponse.analysis_uk || '', 200);
const tags = Array.isArray(aiResponse.tags) ? aiResponse.tags : [];
const importance = aiResponse.importance || 'Низька';

const emojiMap = {
    'Висока': '🔴',
    'Середня': '🟡',
    'Низька': '🟢',
    'Інфо': '⚪'
};
const emoji = emojiMap[importance] || '⚪';

let html = emoji + ' <b>' + title.toUpperCase() + '</b>\n\n';

html += content + '\n\n';

if (analysis && analysis.length > 10) {
    html += '<b>💡 Аналіз:</b>\n<i>' + analysis + '</i>\n\n';
}

if (tags.length > 0) {
    const cleanTags = tags.map(function(t) { return String(t).replace(/[#\s]/g, '').trim(); }).filter(function(t) { return t.length > 0; });
    if (cleanTags.length > 0) {
        html += '<b>🏷 Теги:</b>\n' + cleanTags.map(function(t) { return '#' + t; }).join(' ') + '\n\n';
    }
}

html += 'Джерело:\n🔗 <b><a href="' + link + '">Повна новина</a></b>';

return {
    fullText: html,
    imageUrl: imageUrl,
    importance: importance,
    reaction: '',
    link: link,
    relevance_score: aiResponse.relevance_score || 50
};

// Тема новости (RU/UA/EN). Границы слов: 'ai' не матчит 'said', 'ии' не матчит 'линии'.
const text = ($json.sourceText || '').toLowerCase();

const rx = {
  crypto: /(^|[^а-яёіїєґa-z])(bitcoin|btc|біткоїн|биткоин|биткойн|ethereum|eth|эфириум|solana|солана|крипто|блокчейн|токен|майнинг|майнер|дефи|defi|нфт|nft|кошел|web3|dex|binance|бинанс|альткоин|альткойн|метавселен|смарт-контракт|смарт контракт|cbdc|стейблкоин|стейкинг|usdt|tether|тезер)/,
  ai: /(^|[^а-яёіїєґa-z])(ai|ии|нейросет|нейронн|искусственный интеллект|штучний інтелект|нейромереж|машинное обучение|глубокое обучение|большая языковая модель|генеративн|gpt|chatgpt|openai|llm|claude|gemini|llama|deepseek|deepmind|midjourney|langchain|copilot|chatbot|чат-бот|чатбот|робот|автоматизаци|промпт)/
};

const isAi = rx.ai.test(text);
const isCrypto = rx.crypto.test(text);

let topic = 'general';
if (isAi) topic = 'ai';
else if (isCrypto) topic = 'crypto';

return { ...$json, topic };

// Готовим поисковый запрос для SerpAPI (сам поиск делает нода 'SerpAPI Image Search';
// кодирование query-параметра делает HTTP-нода, поэтому тут — сырой заголовок).
// Заголовок берём из Preprocessing: после Qubax Translate поле title потеряно.
if ($json.imageUrl) {
  return { ...$json, serpQuery: '' };
}
let title = '';
try {
  title = $('Preprocessing').item.json.title || '';
} catch (e) {}
const q = String(title || '').trim().substring(0, 100);
return { ...$json, serpQuery: q };

// Отсев неинтересных новостей (RU/UA/EN). All-items: фильтруем сами и сохраняем pairedItem,
// чтобы вниз по цепочке работали $('Preprocessing').item и подобные ссылки.
const interests = {
  ai_models: { words: ['gpt', 'gpt-4', 'gpt-5', 'chatgpt', 'claude', 'llama', 'gemini', 'openai', 'anthropic', 'deepseek', 'mistral', 'llm', 'foundation model', 'нейросет', 'искусственный интеллект', 'штучний інтелект', 'нейромереж'], weight: 4 },
  ai_tools: { words: ['langchain', 'rag', 'agent', 'copilot', 'cursor', 'chatbot', 'automation', 'n8n', 'api', 'sdk', 'framework', 'fine-tuning', 'prompt', 'ии-агент', 'ии агент', 'автоматизаци', 'чат-бот', 'чатбот', 'промпт'], weight: 3 },
  ai_research: { words: ['transformer', 'diffusion', 'neural', 'deep learning', 'machine learning', 'training', 'benchmark', 'artificial intelligence', 'машинное обучение', 'глубокое обучение', 'генеративн'], weight: 2 },
  crypto_major: { words: ['bitcoin', 'btc', 'ethereum', 'eth', 'solana', 'sol', 'crypto', 'cryptocurrency', 'биткоин', 'биткойн', 'біткоїн', 'эфириум', 'криптовалют', 'криптобирж', 'крипторын', 'крипто'], weight: 4 },
  crypto_defi: { words: ['defi', 'yield', 'staking', 'lending', 'swap', 'liquidity', 'aave', 'uniswap', 'dex', 'стейкинг', 'дефи', 'ликвидност'], weight: 3 },
  crypto_infra: { words: ['blockchain', 'web3', 'layer2', 'l2', 'rollup', 'smart contract', 'dapp', 'token', 'блокчейн', 'смарт-контракт', 'смарт контракт', 'токен', 'майнинг', 'кошел', 'метавселен', 'cbdc', 'цифров', 'евро'], weight: 2 },
  noise: { words: ['airdrop', 'giveaway', 'memecoin', 'shitcoin', 'presale', 'p2e', 'play-to-earn', 'celebrity', 'аирдроп', 'розыгрыш', 'мемкоин'], weight: -8 },
  spam: { words: ['sponsored', 'advertisement', 'paid partnership', 'promo code', 'discount'], weight: -10 }
};

const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const j = items[i].json || {};
  const text = ((j.sourceText || '') + ' ' + (j.title || '')).toLowerCase();
  let score = 0;
  for (const category in interests) {
    const { words, weight } = interests[category];
    const matches = words.filter(w => text.includes(w)).length;
    score += matches * weight;
  }
  if (j.topic === 'ai') score += 10;
  if (j.topic === 'crypto') score += 10;
  if (score >= 3) out.push({ json: { ...j, interestScore: score }, pairedItem: { item: i } });
}
return out;

const preprocessing = $('Preprocessing').item.json;
const link = preprocessing.link || '#';
const title = preprocessing.title || 'Новина';
const imageUrl = preprocessing.imageUrl || '';

function clip(s, max) {
    s = String(s || '');
    if (s.length <= max) return s;
    return s.substring(0, max - 1) + '…';
}

const sourceText = clip(preprocessing.sourceText || '', 400);

let html = '⚠️ <b>' + clip(title, 120).toUpperCase() + '</b>\n\n';
html += sourceText + '\n\n';
html += 'Джерело:\n🔗 <b><a href="' + link + '">Повна новина</a></b>';

return {
  fullText: html,
  imageUrl: imageUrl,
  importance: 'Інфо',
  link: link,
  relevance_score: 50
};

const M = 'qwen3-32b';
const sys = 'You are a tech-news editor covering AI and crypto. Translate news to Ukrainian. Reply ONLY with valid JSON. Fields: importance (one of 4 levels), relevance_score (integer 0-100: how relevant the news is to an AI/crypto professional audience), title_uk, content_uk (3-4 sentences max), analysis_uk (one key consequence, max 200 chars), tags (array). No markdown, no reasoning, only JSON object.';
return $input.all().map(item => {
  const src = item.json?.sourceText || '';
  const msg = sys + String.fromCharCode(10, 10) + 'News: ' + src;
  return { json: { ...item.json, _body: { model: M, messages: [{ role: 'user', content: msg }], temperature: 0.2, max_tokens: 2000 } } };
});

// Склеиваем ответ SerpAPI с исходным item; берём первое изображение.
let base = {};
try {
  base = $('SERP Image Fallback').item.json || {};
} catch (e) {
  base = { ...($json || {}) };
}
delete base.serpQuery;
delete base.error;
const arr = $json.images_results;
const found = Array.isArray(arr) && arr.length ? (arr[0].original || arr[0].thumbnail || '') : '';
base.imageUrl = found || base.imageUrl || '';
return base;
